<!-- Required for Kendo Excel Export -->
<script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/2.4.0/jszip.min.js"></script>
<script src="~/JS/ConsolidateResultReportJS.js"></script>

@using (Html.BeginForm("Index", "ConsolidateResultReport", FormMethod.Post, new { @id = "frmConsolidateResultReport", @class = "form-elements" }))
