                                        pageSizes: [10, 20, 50, 100, 500],
                                        buttonCount: 5,
                                        refresh: true,
                                        pageSize: 100
                                    },
                                    resizable: true,
                                    //groupable: true,
                                    selectable: "single",
                                    filterable: {
                                        extra: false,
                                        operators: {
                                            string: {
                                                clear: "Clear",
                                                eq: "Is equal to",
                                                contains: "Contains"
                                            }
                                        }
                                    },
                                    toolbar: ["excel"],
                                    excel: {
                                        fileName: "ConsolidateResultReport.xlsx",
                                        filterable: true,
                                        allPages: true,
                                        proxyURL: "/Grid/Excel_Export_Save"
