                                        }
                                    }
                                });

                                KendoGridHeightWithoutButton("KConsolidateResultReport");
                            }
                            else {
                                toastr.error("No data Found");
                            }

                            hideLoader();
                        },
                        error: function (xhr, status, error) {
                            console.error("Error fetching data: " + error);
                            hideLoader();
                        }
                    });
                });
            });
        });

        function FillDivision() {
            if ($("#SchoolStandardID").val() === "") {
                $("#StandardDivisionID").fillSelect([]);
                return;
            }

            $("#StandardDivisionID").fillSelect([], {
                ajaxConfig: {
                    type: "POST",
                    url: '/Common/FillStandardDivisionBySchoolStandardID',
                    data: { p_SchoolStandardID: $("#SchoolStandardID").val() },
                    async: false,
                }
            });
        }

        function dataExists() {
            let promise = $.Deferred();

            var SchoolStandardID = $("#SchoolStandardID").val();
            var StandardDivisionID = $("#StandardDivisionID").val();
            var TermID = $("#TermID").val();

            $.ajax({
                type: "Get",
                url: '/ConsolidateResultReport/CheckConsolidateDataExists/',
                data: { SchoolStandardID: SchoolStandardID, StandardDivisionID: StandardDivisionID, TermID: TermID },
                success: function (result) {
                    (result === false && toastr.error("No data")) || toastr.info("Please wait");
                    $("#divStudentData").html("");
                    promise.resolve(result);
                },
                error: function (jqXHR, exception) {
                    alert('Uncaught Error.n' + jqXHR.responseText);
                    promise.resolve(false);
                }
            });
            return promise;
        }
    </script>
}

