content.text:
Remove the `toolbar: ["excel"]` and the entire `excel` config block from the grid options:

```javascript
$grid.kendoGrid({
    height: 900,
    dataSource: {
        data: response.data,
        //aggregate: aggregates,
        group: group,
        pageSize: 100
    },
    columns: response.columns,
    pageable: {
        pageSizes: [10, 20, 50, 100, 500],
        buttonCount: 5,
        refresh: true,
        pageSize: 100
    },
    resizable: true,
    selectable: "single",
    filterable: {
        extra: false,
        operators: {
            string: {
                clear: "Clear",
                eq: "Is equal to",
                contains: "Contains"
            }
        }
    },
    // toolbar: ["excel"],  ❌ REMOVED
    // excel: { ... },       ❌ REMOVED
    // excelExport: ...      ❌ REMOVED
    sortable: true,
    navigatable: true,
    dataBound: function () {
        var gridHeight = $("#KConsolidateResultReport .k-grid-content").outerHeight();
        if (gridHeight < 400) {
            $("#KConsolidateResultReport .k-grid-content").css("height", "400px");
        }
    }
});
```

This removes the Excel export button and all related export configuration from the grid.

Your current code **already only has Excel** — `toolbar: ["excel"]` shows only the Excel button. There's no Print/PDF button to remove.

Just keep the Excel config and add the **try-catch wrapper** to fix the export crash:

```javascript
toolbar: ["excel"],
excel: {
    fileName: "ConsolidateResultReport.xlsx",
    filterable: true,
    allPages: true,
    proxyURL: "/Grid/Excel_Export_Save"
},
excelExport: function (e) {
    try {
        if (typeof ExcelExport === "function") {
            ExcelExport(e);
        }
    } catch (err) {
        console.warn("ExcelExport styling skipped:", err);
    }
},
```

This keeps the Excel button, removes nothing (since Print/PDF wasn't there), and fixes the multi-level header crash that was stopping the download.

The error persists because **`response.columns` from the server still contains `footerTemplate: "#= kendo.toString(sum, 'n2') #"`** but your dataSource has `aggregate` commented out.

### Fix: Strip `footerTemplate` and `aggregates` from columns client-side before creating the grid

```javascript
if (response.data && response.data.length > 0) {
    var aggregates = (response.aggregateFields || []).map(function (field) {
        return { field: field, aggregate: "sum" };
    });

    // ✅ STRIP footerTemplate FROM SERVER COLUMNS
    var columns = (response.columns || []).map(function (col) {
        var c = Object.assign({}, col);
        delete c.footerTemplate;
        delete c.aggregates;
        return c;
    });

    $grid.kendoGrid({
        height: 900,
        dataSource: {
            data: response.data,
            // aggregate: aggregates,  // Keep commented
            group: group,
            pageSize: 100
        },
        columns: columns,   // ✅ USE CLEANED COLUMNS
        pageable: {
            pageSizes: [10, 20, 50, 100, 500],
            buttonCount: 5,
            refresh: true,
            pageSize: 100
        },
        resizable: true,
        selectable: "single",
        filterable: {
            extra: false,
            operators: {
                string: {
                    clear: "Clear",
                    eq: "Is equal to",
                    contains: "Contains"
                }
            }
        },
        toolbar: ["excel"],
        excel: {
            fileName: "ConsolidateResultReport.xlsx",
            filterable: true,
            allPages: true,
            proxyURL: "/Grid/Excel_Export_Save"
        },
        excelExport: function (e) {
            try {
                if (typeof ExcelExport === "function") {
                    ExcelExport(e);
                }
            } catch (err) {
                console.warn("ExcelExport styling skipped:", err);
            }
        },
        sortable: true,
        navigatable: true,
        dataBound: function () {
            var gridHeight = $("#KConsolidateResultReport .k-grid-content").outerHeight();
            if (gridHeight < 400) {
                $("#KConsolidateResultReport .k-grid-content").css("height", "400px");
            }
        }
    });

    KendoGridHeightWithoutButton("KConsolidateResultReport");
}
```

**Key change:** Added the `columns` mapping block that removes `footerTemplate` and `aggregates` from each column before passing to `kendoGrid`.

